"""matplotlib.dviread — DVI (TeX Device Independent) file reader shim.

The plotly backend doesn't compile LaTeX in-process, so we can't fully
parse DVI streams. The classes below preserve the upstream surface
(constructor signatures, context-manager protocol, ``__iter__`` /
``__getitem__`` shape) and store the inputs so introspection works,
but iterate empty by default. Any TeX-rendered text falls back to
plotly's HTML/MathJax rendering.
"""


class Dvi:
    """Iterator over the pages of a ``.dvi`` file."""

    def __init__(self, filename, dpi):
        self.file = filename
        self.dpi = float(dpi)
        self.fonts = {}
        self.pages = []
        self._closed = False

    def __iter__(self):
        return iter(self.pages)

    def close(self):
        self._closed = True

    def __enter__(self):
        return self

    def __exit__(self, *args):
        self.close()
        return False


class DviFont:
    """A font referenced from a DVI stream."""

    def __init__(self, scale, tfm, texname, vf):
        self.scale = float(scale) if scale is not None else 0.0
        self.tfm = tfm
        self.texname = texname
        self.vf = vf
        self.widths = []

    @property
    def size(self):
        """Font size in points (scale is in scaled points; 65536 = 1pt)."""
        return self.scale / 65536.0

    def __eq__(self, other):
        return (isinstance(other, DviFont)
                and self.texname == other.texname
                and self.scale == other.scale)

    def __hash__(self):
        return hash((self.texname, self.scale))


class Tfm:
    """Parsed TeX Font Metrics file. The shim stores the path; metric
    lookups return zero-width since we don't bundle a TFM parser."""

    def __init__(self, filename):
        self.filename = filename
        self.checksum = 0
        self.design_size = 10.0
        self.width = {}
        self.height = {}
        self.depth = {}

    def __getitem__(self, glyph):
        return (self.width.get(glyph, 0),
                self.height.get(glyph, 0),
                self.depth.get(glyph, 0))


class Vf(Dvi):
    """Virtual Font reader — same surface as :class:`Dvi`."""

    def __init__(self, filename):
        super().__init__(filename, dpi=1.0)


class PsFont:
    """PostScript font entry from a psfonts.map file."""

    def __init__(self, texname, psname, effects, encoding=None, filename=None):
        self.texname = texname
        self.psname = psname
        self.effects = dict(effects) if effects else {}
        self.encoding = encoding
        self.filename = filename


class PsfontsMap:
    """psfonts.map lookup table — TeX font name → PsFont entry."""

    def __init__(self, filename):
        self.filename = filename
        self._map = {}
        # Try to parse the file if it exists, otherwise leave empty.
        try:
            with open(filename, 'r', encoding='utf-8', errors='replace') as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith('%'): continue
                    parts = line.split()
                    if not parts: continue
                    texname = parts[0]
                    psname = parts[1] if len(parts) >= 2 else texname
                    self._map[texname] = PsFont(texname, psname, {},
                                                  filename=parts[-1] if parts[-1].endswith('.pfb') else None)
        except (FileNotFoundError, OSError):
            pass

    def __getitem__(self, texname):
        return self._map.get(texname)

    def __contains__(self, texname):
        return texname in self._map


# ─── Added: missing public names from upstream dviread.py ───────────


import os
from collections import namedtuple


# Public namedtuples matching upstream's API surface.
Page = namedtuple('Page', ['text', 'boxes', 'height', 'width', 'descent'])
Text = namedtuple('Text', ['x', 'y', 'font', 'glyph', 'width'])
Box = namedtuple('Box', ['x', 'y', 'height', 'width'])


def find_tex_file(filename):
    """Use ``kpsewhich`` (the standard TeX file-finder) to locate a TeX
    file. Returns the absolute path or ``None`` if kpsewhich isn't
    available."""
    try:
        import subprocess
        r = subprocess.run(['kpsewhich', filename], capture_output=True,
                           text=True, timeout=2)
        path = r.stdout.strip()
        return path or None
    except Exception:
        return None


# ─── Added: Text namedtuple-compatible accessors ────────────────────


# Text is a namedtuple — add properties for the upstream-style accessors.
def _text_font_path(self):    return getattr(self.font, 'fname', None) if hasattr(self, 'font') else None
def _text_font_size(self):    return getattr(self.font, 'size', 12) if hasattr(self, 'font') else 12
def _text_font_effects(self): return getattr(self.font, 'effects', {}) if hasattr(self, 'font') else {}
def _text_glyph_name_or_index(self): return getattr(self, 'glyph', None)

# Use a regular class instead of namedtuple-only access.
_OrigText = Text
class Text(_OrigText):
    @property
    def font_path(self):    return _text_font_path(self)
    @property
    def font_size(self):    return _text_font_size(self)
    @property
    def font_effects(self): return _text_font_effects(self)
    @property
    def glyph_name_or_index(self): return _text_glyph_name_or_index(self)
